#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int id;
    ll key;
    char dir;   // original dir: 'E' or 'S'
    ll x, y;    // row, col
} Ant;

typedef struct {
    ll t;
    ll side;    // for E: row exit (1..H), for S: col exit (1..W)
    int id;
} Event;

static int cmpKey(const void *a, const void *b) {
    const Ant *A = (const Ant *)a;
    const Ant *B = (const Ant *)b;
    if (A->key < B->key) return -1;
    if (A->key > B->key) return 1;
    return A->id - B->id;
}

static int cmpX(const void *a, const void *b) {
    const Ant *A = (const Ant *)a;
    const Ant *B = (const Ant *)b;
    if (A->x < B->x) return -1;
    if (A->x > B->x) return 1;
    return A->id - B->id;
}

static int cmpY(const void *a, const void *b) {
    const Ant *A = (const Ant *)a;
    const Ant *B = (const Ant *)b;
    if (A->y < B->y) return -1;
    if (A->y > B->y) return 1;
    return A->id - B->id;
}

static int cmpEvent(const void *a, const void *b) {
    const Event *A = (const Event *)a;
    const Event *B = (const Event *)b;
    if (A->t < B->t) return -1;
    if (A->t > B->t) return 1;
    if (A->id < B->id) return -1;
    if (A->id > B->id) return 1;
    return 0;
}

int main(void) {
    int N;
    ll H, W;
    if (scanf("%d %lld %lld", &N, &H, &W) != 3) return 0;

    Ant *ants = (Ant *)malloc(sizeof(Ant) * N);
    Ant *group = (Ant *)malloc(sizeof(Ant) * N);
    Event *events = (Event *)malloc(sizeof(Event) * N);

    for (int i = 0; i < N; i++) {
        ll r, c;
        char d[4];
        scanf("%lld %lld %s", &r, &c, d);
        ants[i].id = i + 1;
        ants[i].x = r;
        ants[i].y = c;
        ants[i].dir = d[0];
        ants[i].key = r + c;
    }

    qsort(ants, N, sizeof(Ant), cmpKey);

    int ecount = 0;
    int l = 0;
    while (l < N) {
        int r = l;
        while (r < N && ants[r].key == ants[l].key) r++;

        int m = r - l;
        for (int i = 0; i < m; i++) group[i] = ants[l + i];

        // Ants on same diagonal interact as if labels are permuted.
        // Sort by row for original positions.
        qsort(group, m, sizeof(Ant), cmpX);

        Ant *orig = (Ant *)malloc(sizeof(Ant) * m);
        for (int i = 0; i < m; i++) orig[i] = group[i];

        // Destination exits:
        // E ants correspond to right edge exits ordered by row.
        // S ants correspond to bottom edge exits ordered by column.
        Ant *E = (Ant *)malloc(sizeof(Ant) * m);
        Ant *S = (Ant *)malloc(sizeof(Ant) * m);
        int ec = 0, sc = 0;
        for (int i = 0; i < m; i++) {
            if (orig[i].dir == 'E') E[ec++] = orig[i];
            else S[sc++] = orig[i];
        }

        qsort(E, ec, sizeof(Ant), cmpX); // by row
        qsort(S, sc, sizeof(Ant), cmpY); // by col

        // Build ordered list of exit points along boundary:
        // first all bottom exits by increasing column, then right exits by increasing row
        // and assign them to ants in increasing row order.
        int p = 0;
        for (int i = 0; i < sc; i++, p++) {
            ll t = H - orig[p].x + 1;
            events[ecount].t = t;
            events[ecount].side = S[i].y;
            events[ecount].id = orig[p].id;
            ecount++;
        }
        for (int i = 0; i < ec; i++, p++) {
            ll t = W - orig[p].y + 1;
            events[ecount].t = t;
            events[ecount].side = E[i].x;
            events[ecount].id = orig[p].id;
            ecount++;
        }

        free(orig);
        free(E);
        free(S);
        l = r;
    }

    qsort(events, ecount, sizeof(Event), cmpEvent);

    for (int i = 0; i < ecount; i++) {
        if (i) putchar('\n');
        printf("%d", events[i].id);
    }

    free(ants);
    free(group);
    free(events);
    return 0;
}

