    int H, W, N;
    cin >> H >> W >> N;

    vector<Ant> ants(N);
    // Map from position to list of ant indices currently there
    map<pair<int,int>, vector<int>> pos_map;

    for (int i = 0; i < N; i++) {
        int x, y;
        char d;
        cin >> x >> y >> d;
        ants[i].id = i + 1;
        ants[i].r = x;
        ants[i].c = y;
        ants[i].dir = (d == 'E') ? 0 : 1;
        ants[i].fallen = false;
        pos_map[{x, y}].push_back(i);
    }

    vector<int> fall_order;
    int fallen_count = 0;

    while (fallen_count < N) {
        // Move all ants one step
        // For each ant, compute next position
        vector<pair<int,int>> next_pos(N, {-1, -1});
        for (int i = 0; i < N; i++) {
            if (ants[i].fallen) continue;
            int nr = ants[i].r, nc = ants[i].c;
            if (ants[i].dir == 0) nc++;
            else nr++;
            next_pos[i] = {nr, nc};
        }

        // Determine which ants fall
        vector<int> falling;
        for (int i = 0; i < N; i++) {
            if (ants[i].fallen) continue;
            int nr = next_pos[i].first, nc = next_pos[i].second;
            if (nr > H || nc > W) {
                falling.push_back(i);
            }
        }

        // Sort falling ants by id for output
        sort(falling.begin(), falling.end(),
             [&](int a, int b) { return ants[a].id < ants[b].id; });
        for (int idx : falling) {
            ants[idx].fallen = true;
            fall_order.push_back(ants[idx].id);
            // Remove from pos_map
            auto &vec = pos_map[{ants[idx].r, ants[idx].c}];
            vec.erase(remove(vec.begin(), vec.end(), idx), vec.end());
            if (vec.empty()) pos_map.erase({ants[idx].r, ants[idx].c});
        }
        fallen_count += falling.size();

        // Build new positions for surviving ants
        map<pair<int,int>, vector<int>> new_positions;
        for (int i = 0; i < N; i++) {
            if (ants[i].fallen) continue;
            int nr = next_pos[i].first, nc = next_pos[i].second;
            new_positions[{nr, nc}].push_back(i);
        }

        // Clear old positions from pos_map for surviving ants
        for (int i = 0; i < N; i++) {
            if (ants[i].fallen) continue;
            auto &vec = pos_map[{ants[i].r, ants[i].c}];
            vec.erase(remove(vec.begin(), vec.end(), i), vec.end());
            if (vec.empty()) pos_map.erase({ants[i].r, ants[i].c});
