struct Ant {
    int id;
    long long x, y; // 1-indexed row, col
    char d;         // 'E' or 'S'
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, N;
    cin >> H >> W >> N;

    vector<Ant> ants(N);
    for (int i = 0; i < N; ++i) {
        cin >> ants[i].x >> ants[i].y >> ants[i].d;
        ants[i].id = i + 1;
    }

    /*
      Key observation:
      Consider each ant as a "particle" moving along monotone paths.
      Interactions only happen when an east-moving ant and a south-moving ant
      reach the same square at the same time.

      Let t be time. Then:
        East ant:  (x, y+t)
        South ant: (x+t, y)

      They meet iff:
        xE = xS + t
        yE + t = yS
      so:
        xE + yE = xS + yS
      Therefore only ants with the same value of x+y can ever interact.

      Along one diagonal s = x+y, ants preserve order and behave like passing
      through each other with label swaps. This is the standard "ants swapping
      identities" phenomenon.

      For a fixed diagonal s:
      - East ants are ordered by increasing row x.
      - South ants are ordered by increasing column y.
      When considering exits:
      - An east-moving trajectory exits at the right border at time W - y.
      - A south-moving trajectory exits at the bottom border at time H - x.

      After all swaps, the multiset of physical exit events is unchanged; only
      labels assigned to them are permuted.
      The permutation is obtained by matching ants in the order they appear on
      the diagonal to exit trajectories in the order they leave along that same
      diagonal:
        initial order on diagonal: by increasing x (equiv decreasing y)
          with E before S at same square impossible initially since distinct.
        More concretely, collect all ants on the diagonal and sort by x.
        The sequence of labels in this order is preserved.
        Collect all exit trajectories on this diagonal:
          - east trajectories exit on right border at row x, time W-(s-x)
          - south trajectories exit on bottom border at col y=s-x
        Sort these trajectories by exit time, and for ties by border position
        corresponding to smaller ant id later globally; but physical events at
        same time on distinct squares do not interact. For label assignment on
        one diagonal, the correct order is by border coordinate increasing:
          right-border exits correspond to increasing x,
          bottom-border exits correspond to increasing y.
        Equivalently, sort trajectories by their endpoint coordinate along the
        concatenated border path:
          right border from top to bottom, then bottom border from left to right.
        This is the standard mapping for E/S ants on same x+y.
     */

    map<long long, vector<Ant>> groups;
    for (auto &a : ants) groups[a.x + a.y].push_back(a);

    vector<pair<long long,int>> answer; // (fall time, ant id)

    for (auto &kv : groups) {
        auto vec = kv.second;

        // Initial order along diagonal: increasing x
        sort(vec.begin(), vec.end(), [](const Ant& a, const Ant& b) {
            if (a.x != b.x) return a.x < b.x;
            return a.y > b.y;
        });

        vector<int> labels;
        for (auto &a : vec) labels.push_back(a.id);

        struct Exit {
            int type; // 0 = right border, 1 = bottom border
            long long coord; // row if right, col if bottom
            long long time;
        };

        vector<Exit> exits;
        for (auto &a : vec) {
            if (a.d == 'E') {
                exits.push_back({0, a.x, W - a.y});
            } else {
                exits.push_back({1, a.y, H - a.x});
            }
        }

        // Sort exit slots by border order:
        // right border top->bottom, then bottom border left->right
        sort(exits.begin(), exits.end(), [](const Exit& a, const Exit& b) {
            if (a.type != b.type) return a.type < b.type;
            return a.coord < b.coord;
        });

        for (int i = 0; i < (int)labels.size(); ++i) {
            answer.push_back({exits[i].time, labels[i]});
        }
    }

    sort(answer.begin(), answer.end(), [](const auto& a, const auto& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    for (auto &p : answer) {
        cout << p.second << "\n";
    }

    return 0;
}

