            ant[1] += dc[ant[2]]

        # Check who fell off
        remaining = []
        fallen_this_step = []
        t_current = None

        for ant in ants:
            if ant[0] < 0 or ant[0] >= H or ant[1] < 0 or ant[1] >= W:
                fallen_this_step.append(ant[3])
            else:
                remaining.append(ant)

        results.extend(fallen_this_step)
        ants = remaining

        # Handle collisions
        pos_groups = defaultdict(list)
        for ant in ants:
            pos_groups[(ant[0], ant[1])].append(ant)

        for (r, c), group in pos_groups.items():
