import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt(), W = sc.nextInt(), N = sc.nextInt();
        int[] r = new int[N+1], c = new int[N+1];
        char[] dir = new char[N+1];
        for (int i = 1; i <= N; i++) {
            r[i] = sc.nextInt(); c[i] = sc.nextInt();
            dir[i] = sc.next().charAt(0); // 'E' or 'S'
        }

        List<Integer> result = new ArrayList<>();
        boolean[] alive = new boolean[N+1];
        Arrays.fill(alive, true);
        alive[0] = false;

        while (true) {
            boolean anyAlive = false;
            for (int i = 1; i <= N; i++) if (alive[i]) { anyAlive = true; break; }
            if (!anyAlive) break;

            // Move
            for (int i = 1; i <= N; i++) {
                if (!alive[i]) continue;
                if (dir[i] == 'E') c[i]++;
                else r[i]++;
            }
            // Check falls
            List<Integer> fell = new ArrayList<>();
            for (int i = 1; i <= N; i++) {
                if (!alive[i]) continue;
                if (r[i] > H || c[i] > W) { fell.add(i); alive[i] = false; }
            }
            Collections.sort(fell);
            result.addAll(fell);
            // Handle collisions
            Map<Long, List<Integer>> pos = new HashMap<>();
            for (int i = 1; i <= N; i++) {
                if (!alive[i]) continue;
                long key = (long)r[i]*10001+c[i];
                pos.computeIfAbsent(key, k->new ArrayList<>()).add(i);
            }
            for (var e : pos.entrySet()) {
                List<Integer> ants = e.getValue();
                if (ants.size() == 2) {
                    int a = ants.get(0), b = ants.get(1);
                    boolean white = (r[a]+c[a])%2==0;
                    if (white) { char tmp=dir[a]; dir[a]=dir[b]; dir[b]=tmp; }
                }
            }
        }
        for (int x : result) System.out.println(x);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int H = Integer.parseInt(st.nextToken());
        int W = Integer.parseInt(st.nextToken());
        int N = Integer.parseInt(st.nextToken());

        // Store ants: each ant has number, x, y, direction (0=east, 1=south)
        int[] num = new int[N];
        int[] x = new int[N];
        int[] y = new int[N];
        int[] dir = new int[N]; // 0 east, 1 south

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            num[i] = Integer.parseInt(st.nextToken());
            y[i] = Integer.parseInt(st.nextToken()) - 1; // 0-based row
            x[i] = Integer.parseInt(st.nextToken()) - 1; // 0-based col
            char d = st.nextToken().charAt(0);
            dir[i] = (d == 'E') ? 0 : 1;
        }

        // We'll simulate until all ants have fallen.
        // Since H,W <= 1000 and N <= 100000, but total steps bounded by max(H,W) 
        // because each step moves one cell, and max distance to edge is max(H,W).
        // Use a priority queue to always process the earliest fall time.
        // But collisions can change directions, so we need to simulate step by step.
        // However, we can simulate efficiently by processing events in time order.

        // For each ant, compute its time to fall if no collisions.
        // But collisions change direction, so we need to simulate collisions.
        // Since ants only move east or south, collisions only happen when two ants
        // are on a diagonal path: one going east, one going south, meeting at a cell.
        // They meet only if they start such that one is above and to the left of the other.
        // After collision on white, they swap directions, which essentially means they
        // continue as if they passed through each other but with swapped identities.
        // On black, they keep direction, so they cross without interaction.
        // So the key is: on white squares, ants swap directions (and effectively swap identities).
        // This is similar to ants on a line where they bounce off each other.
        // The order of falling can be determined by simulating the paths with identity swaps.

        // We can treat each ant's trajectory as a line: east ants move right, south ants move down.
        // When two ants meet on a white square, they swap their "directions", which is equivalent
        // to them exchanging their future paths. So we can think of each ant continuing straight,
        // but the identity follows the path that turns. This is like ants passing through each other
        // but with labels swapped.
        // Therefore, the set of positions where ants fall off is the same as if they all moved straight,
        // but the order in which they fall (which number falls when) is determined by swapping labels
        // at white collisions.

        // So we can simulate all ants moving straight, compute their fall times and exit points,
        // then process collisions to swap identities.
        // But we need the sequence of falling ants (by number). 
        // Another approach: since collisions only swap identities, we can simulate all ants
        // moving straight, compute for each "path" the time it reaches the edge, then
        // process all collision events in time order to swap the numbers.

        // Let's implement this.

        // Step 1: Compute for each ant its fall time and exit position if moving straight.
        // East ant: falls when x == W, time = (W-1 - x[i]) + 1 = W - x[i]
        // South ant: falls when y == H, time = (H-1 - y[i]) + 1 = H - y[i]
        int[] fallTime = new int[N];
        int[] exitX = new int[N]; // column at exit (only relevant for south ants? we may not need)
        int[] exitY = new int[N]; // row at exit

        for (int i = 0; i < N; i++) {
            if (dir[i] == 0) { // east
                fallTime[i] = W - x[i];
                exitX[i] = W - 1; // falls at right edge
                exitY[i] = y[i];
            } else { // south
                fallTime[i] = H - y[i];
                exitX[i] = x[i];
                exitY[i] = H - 1;
            }
        }

        // Step 2: Find all potential collision events.
        // A collision happens when an east ant and a south ant meet at a cell.
        // For east ant at (y1, x1) and south ant at (y2, x2):
        // They meet if y1 == y2 + t and x1 + t == x2 for some t >= 0.
        // => t = y1 - y2 = x2 - x1, so y1 - y2 == x2 - x1 >= 0.
        // Meeting time = t, meeting cell = (y1, x1 + t) = (y2 + t, x2)
        // They meet only if t >= 0 and within board (before either falls).
        // Also they must both still be on board at that time.
        // So for each pair (east ant i, south ant j):
        //   dy = y[i] - y[j], dx = x[j] - x[i]
        //   if dy == dx and dy >= 0:
        //        t = dy
        //        if t < min(fallTime[i], fallTime[j]): they collide at time t+1? 
        //        Actually they start at time 0, after t steps they are at same cell.
        //        At time t (after t moves), they occupy same cell.
        //        Collision occurs at time t (0-indexed), meaning after t moves.
        //        But careful: if t == 0 they start on same cell? Problem says initially distinct squares.
        //        So t > 0.
        //        The collision time is t (the number of steps after start when they meet).
        //        They both move at time 1,2,..., so at time t they have moved t steps.
        //        We'll store collision event with time = t.

        // We'll store events as: time, ant1, ant2
        List<int[]> events = new ArrayList<>();
        // Map from time to list of collisions? We'll sort later.

        for (int i = 0; i < N; i++) {
            if (dir[i] != 0) continue; // only east ants
            for (int j = 0; j < N; j++) {
                if (dir[j] != 1) continue; // only south ants
                int dy = y[i] - y[j];
                int dx = x[j] - x[i];
                if (dy == dx && dy > 0) {
                    int t = dy;
                    if (t < fallTime[i] && t < fallTime[j]) {
                        events.add(new int[]{t, i, j});
                    }
                }
            }
        }

        // Sort events by time
        events.sort((a, b) -> Integer.compare(a[0], b[0]));

        // Now process collisions in order, swapping the numbers of the two ants.
        // We'll maintain an array mapping from ant index to its current number.
        int[] antNumber = new int[N];
        for (int i = 0; i < N; i++) antNumber[i] = num[i];

        // Also we need to know for each ant its current direction? No, direction doesn't change 
        // for the "identity" after swap? Wait: when ants swap directions on white, 
        // it means the east ant becomes south and south becomes east.
        // In our "straight line" model, the identity follows the turning path.
        // That is exactly equivalent to swapping the numbers between the two ants.
        // So after collision, the ant that was originally east now has the number of the south ant,
        // and continues moving south? Actually careful: 
        // If ant A (east) and ant B (south) collide on white:
        //   A turns south, B turns east.
        // So after collision, A moves south, B moves east.
        // In the "straight line" model, if we imagine ants pass through, 
        // the ant that continues east is the one that was originally east (but now with B's number?).
        // Actually the standard trick: if ants bounce off each other, it's equivalent to them passing through 
        // with labels swapped. Here, they don't bounce; they turn. But turning is like swapping identities 
        // because the path that was going east now goes south, and vice versa.
        // So yes, swapping numbers at collision gives correct result.

        // So we process events: for each collision, swap antNumber[i] and antNumber[j].
        // But note: after swapping, further collisions involve the same ant indices but with swapped numbers.
        // This works because the physical ants continue on their straight paths; only labels change.

        for (int[] ev : events) {
            int i = ev[1], j = ev[2];
            int tmp = antNumber[i];
            antNumber[i] = antNumber[j];
            antNumber[j] = tmp;
        }

        // Now we have final numbers for each ant path.
        // The fall time for each ant index is already computed.
        // We need to output the sequence of ants (by number) in order of fall time.
        // If multiple fall at same time, smaller number first.

        // Create list of (fallTime, number) pairs
        List<int[]> falls = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            falls.add(new int[]{fallTime[i], antNumber[i]});
        }

        // Sort by fallTime, then by number
        falls.sort((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });

        // Output
        StringBuilder sb = new StringBuilder();
        for (int[] f : falls) {
            sb.append(f[1]).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

/*
Key idea:
- Ants only move East or South.
- A collision can only happen between an East-moving ant and a South-moving ant.
- They meet only when the East ant is to the west and the South ant is to the north,
  and the horizontal/vertical distances to the intersection are equal.
- If they meet on a white square, they swap directions; on a black square, nothing changes.

Observation:
Swapping directions between two labeled ants is equivalent to the ants passing through each other
while exchanging identities. On black squares they literally pass through; on white squares they
swap directions, which is also exactly identity exchange.

Therefore, if we ignore identities, each "trajectory" just moves straight East or South forever
until leaving the board. The only effect of collisions is to permute which label is attached to
which trajectory.

Model:
- Each ant starts on one diagonal d = r + c.
- Any interaction only happens between ants on the same diagonal, so different diagonals are independent.
- On one diagonal:
    * East ants correspond to trajectories ending at the right edge, ordered by starting row.
    * South ants correspond to trajectories ending at the bottom edge, ordered by starting column.
- Identity exchanges preserve the order along the diagonal, so if we sort all ants on that diagonal
  by row (equivalently column descending), then sort all exit trajectories by exit time and tie-break
  by endpoint position, the k-th ant gets the k-th trajectory.

Exit trajectory:
- East from (r,c) exits at time W - c + 1 from endpoint (r, W+1)
- South from (r,c) exits at time H - r + 1 from endpoint (H+1, c)

For each diagonal:
1) collect ants
2) build all exit trajectories from their initial directions
3) sort ants by row ascending
4) sort trajectories by (time, endpoint coordinate), where endpoint coordinate is:
      for right edge use row,
      for bottom edge use column
5) assign k-th trajectory to k-th ant label

Finally sort all ants by (fall time, id) and output ids.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Ant {
        int id;
        int r, c;
        char dir;
        int diag;

        Ant(int id, int r, int c, char dir) {
            this.id = id;
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.diag = r + c;
        }
    }

    static class ExitInfo {
        long time;
        int pos; // row if right edge, column if bottom edge

        ExitInfo(long time, int pos) {
            this.time = time;
            this.pos = pos;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();
        int N = fs.nextInt();

        Map<Integer, ArrayList<Ant>> groups = new HashMap<>();

        for (int i = 1; i <= N; i++) {
            int r = fs.nextInt();
            int c = fs.nextInt();
            String s = fs.next();
            char dir = s.charAt(0); // 'E' or 'S'
            Ant ant = new Ant(i, r, c, dir);
            groups.computeIfAbsent(ant.diag, k -> new ArrayList<>()).add(ant);
        }

        long[] fallTime = new long[N + 1];

        for (ArrayList<Ant> list : groups.values()) {
            list.sort(Comparator.comparingInt(a -> a.r));

            ArrayList<ExitInfo> exits = new ArrayList<>();
            for (Ant a : list) {
                if (a.dir == 'E') {
                    exits.add(new ExitInfo((long) W - a.c + 1, a.r));
                } else { // 'S'
                    exits.add(new ExitInfo((long) H - a.r + 1, a.c));
                }
            }

            exits.sort((x, y) -> {
                if (x.time != y.time) return Long.compare(x.time, y.time);
                return Integer.compare(x.pos, y.pos);
            });

            for (int i = 0; i < list.size(); i++) {
                fallTime[list.get(i).id] = exits.get(i).time;
            }
        }

        Integer[] ids = new Integer[N];
        for (int i = 0; i < N; i++) ids[i] = i + 1;

        Arrays.sort(ids, (a, b) -> {
            if (fallTime[a] != fallTime[b]) return Long.compare(fallTime[a], fallTime[b]);
            return Integer.compare(a, b);
        });

        StringBuilder out = new StringBuilder();
        for (int id : ids) {
            out.append(id).append('\n');
        }
        System.out.print(out.toString());
    }
}
